full/powershell/cursor/ollama-embed/open.copy:
# Keep generated configuration files out of version control.
if (-not (Test-Path .gitignore)) { New-Item -ItemType File -Path .gitignore | Out-Null }
Add-Content -Path .gitignore -Value '.chunkhound.json'
# Configure ChunkHound with Ollama embeddings and OpenCode CLI for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
@'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "opencode-cli",
    "model": "opencode/deepseek-v4.1-flash"
  }
}
'@ | Set-Content -Path '.chunkhound.json' -Encoding utf8

# Configure Cursor to connect to ChunkHound via MCP.
if (Test-Path '.cursor/mcp.json') {
Write-Host @'
.cursor/mcp.json already exists — merge this block into it manually:
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
'@
} else {
New-Item -ItemType Directory -Force -Path '.cursor' | Out-Null
@'
{
  "mcpServers": {
    "ChunkHound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
'@ | Set-Content -Path '.cursor/mcp.json' -Encoding utf8
}

